1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	export async function idCursoQA101(page: Page): Promise<number> {
19	  await page.goto('/course/view.php?name=QA101');
20	  return (await configMoodle(page)).courseId;
21	}
22	
23	// ---------------------------------------------------------------------------------------------------------
24	// Examen
25	
26	export async function abrirFormularioExamen(page: Page, curso: number) {
27	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
28	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible();
29	}
30	
31	/** Guarda con "Save and display" y devuelve el cmid del examen creado o editado. */
32	export async function guardarExamen(page: Page): Promise<number> {
33	  await page.getByRole('button', { name: 'Save and display' }).click();
34	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
35	  return Number(new URL(page.url()).searchParams.get('id'));
36	}
37	
38	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
39	  await abrirFormularioExamen(page, curso);
40	  await page.locator('#id_name').fill(nombre);
41	  return guardarExamen(page);
42	}
43	
44	export async function eliminarExamen(page: Page, cmid: number) {
45	  const { sesskey } = await configMoodle(page);
46	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
47	  await page.getByRole('button', { name: 'Yes', exact: true }).click();
48	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
49	}
50	
51	// ---------------------------------------------------------------------------------------------------------
52	// Banco de preguntas
53	
54	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
55	export async function cmidBanco(page: Page, curso: number): Promise<number> {
56	  await page.goto(`/question/banks.php?courseid=${curso}`);
57	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
58	  await expect(banco).toBeAttached();
59	  return Number(await banco.getAttribute('data-cmid'));
60	}
61	
62	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
63	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
64	
65	export const filaCategoria = (page: Page, nombre: string): Locator =>
66	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
67	
68	export const filaPregunta = (page: Page, nombre: string): Locator =>
69	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
70	
71	/**
72	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
73	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
74	 */
75	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
76	  await page.goto(urlCategorias(banco));
77	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
78	  await page.waitForLoadState('networkidle');
79	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
80	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
81	  await modal.locator('input[name="name"]').fill(nombre);
82	  await modal.locator('[data-action="save"]').click();
83	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
84	  await page.reload();
85	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
86	  const { contextid } = await configMoodle(page);
87	  return { id: String(id), contexto: String(contextid) };
88	}
89	
90	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
91	export async function escribirEditor(page: Page, iframe: string, texto: string) {
92	  await expect(page.locator(iframe)).toBeVisible();
93	  const cuerpo = page.frameLocator(iframe).locator('body');
94	  await cuerpo.click();
95	  await cuerpo.fill(texto);
96	}
97	
98	/** Crea una pregunta desde el botón "Create a new question ..." del banco, dentro de la categoría indicada. */
99	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
100	  await page.goto(urlBanco(banco, categoria));
101	  // edit.php:73 corta la página sin pintar el banco mientras la migración de mod_qbank siga en la cola de tareas ad hoc.
102	  await expect(
103	    page.getByRole('alert').filter({ hasText: 'transfer_question_categories' }),
104	    'Entorno: las tareas ad hoc de mod_qbank no terminaron; revisar el cron o ejecutarlas antes de esta prueba',
105	  ).toHaveCount(0);
106	  // Con teclado, no con click: en móvil, el punto de click de Playwright cae sobre elementos que están ANTES del botón
107	  // en el flujo (h2, filtros) o bajo la barra fija, aunque nada lo tape en el DOM. El teclado no depende de coordenadas
108	  // y recorre el mismo botón, el mismo diálogo y el mismo envío. El botón nace deshabilitado hasta que carga chooser.js
109	  // y el diálogo solo habilita "Add" al elegir un tipo: se espera cada estado porque press() no lo hace.
110	  const crear = page.getByRole('button', { name: /create a new question/i });
111	  await expect(crear).toBeEnabled();
112	  await crear.press('Enter');
113	  const tipoPregunta = page.locator(`#item_qtype_${tipo}`);
114	  await expect(tipoPregunta).toBeVisible();
115	  await tipoPregunta.press('Space');
116	  await expect(tipoPregunta).toBeChecked();
117	  const agregar = page.locator('#chooserform input.submitbutton');
118	  await expect(agregar).toBeEnabled();
119	  await agregar.press('Enter');
120	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
121	
122	  await page.locator('#id_name').fill(nombre);
123	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
124	  if (tipo === 'multichoice') {
125	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
126	    await page.locator('#id_fraction_0').selectOption({ label: '100%' });
127	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
128	  } else if (tipo === 'truefalse') {
129	    await page.locator('#id_correctanswer').selectOption({ label: 'True' });
130	  }
131	  await page.locator('#id_submitbutton').click();
132	  await expect(page).toHaveURL(/question\/edit\.php/);
133	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
134	}
135	
136	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
137	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
138	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
139	  await page.waitForLoadState('networkidle');
140	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
141	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
142	
143	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
144	  await page.locator('#switch-question-bank').click();
145	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
146	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
147	  // Tras visitarlo, el banco también aparece en "recientes" con el mismo data-newmodid; "banks in course" siempre lo lista.
148	  await page.locator(`.course-shared-banks a[data-newmodid="${banco}"]`).click();
149	
150	  const filtro = page.locator('[data-filter-type="category"]');
151	  const entrada = filtro.locator('div.form-autocomplete-input input');
152	  await entrada.click();
153	  await entrada.fill(categoria);
154	  await filtro.locator('.form-autocomplete-suggestions li', { hasText: categoria }).click();
155	  await page.locator('[data-filteraction="apply"]').click();
156	
157	  for (const nombre of preguntas) {
158	    await filaPregunta(page, nombre).locator('input[type="checkbox"]').check();
159	  }
160	  await page.getByRole('button', { name: 'Add selected questions to the quiz' }).click();
161	  await expect(page).toHaveURL(/mod\/quiz\/edit\.php/);
162	}
163	
164	/** Borra todas las preguntas de la categoría con la confirmación del banco y comprueba que ya no se listan. */
165	export async function eliminarPreguntas(page: Page, banco: number, categoria: Categoria) {
166	  await page.goto(urlBanco(banco, categoria));
167	  const nombres = await page.locator('#categoryquestions tbody input[type="checkbox"]')
168	    .evaluateAll((casillas) => casillas.map((c) => (c as HTMLInputElement).name));
169	  const ids = nombres.filter((n) => /^q\d+$/.test(n));
170	  if (!ids.length) return;
171	  const { sesskey } = await configMoodle(page);
172	  const parametros = new URLSearchParams({
173	    deleteselected: ids[0].slice(1),
174	    deleteall: '1',
175	    sesskey,
176	    cmid: String(banco),
177	    returnurl: `/question/edit.php?cmid=${banco}`,
178	  });
179	  ids.forEach((q) => parametros.set(q, '1'));
180	  await page.goto(`/question/bank/deletequestion/delete.php?${parametros}`);
181	  await page.getByRole('button', { name: 'Delete', exact: true }).click();
182	  await expect(page).toHaveURL(/question\/edit\.php/);
183	  await page.goto(urlBanco(banco, categoria));
184	  await expect(page.locator('#categoryquestions tbody tr')).toHaveCount(0);
185	}
186	
187	export async function eliminarCategoria(page: Page, banco: number, categoria: Categoria) {
188	  const { sesskey } = await configMoodle(page);
189	  await page.goto(`${urlCategorias(banco)}&delete=${categoria.id}&sesskey=${sesskey}`);
190	  await expect(page).toHaveURL(/managecategories\/category\.php/);
191	}
192	
193	// ---------------------------------------------------------------------------------------------------------
194	// Intento y calificación
195	
196	/** Radio de una opción, con el mismo criterio de nombre accesible que elegir() en helpers.ts. */
197	export function opcion(page: Page, pregunta: number, texto: string): Locator {
198	  return bloquePregunta(page, pregunta).getByRole('radio', { name: new RegExp(`^([a-z0-9]+\\. )?${texto}$`, 'i') });
199	}
200	
201	/** Celda de estado de una pregunta en la tabla de summary.php. */
202	export const estadoEnResumen = (page: Page, pregunta: number): Locator =>
203	  page.locator(`table.quizsummaryofattempt tr.quizsummary${pregunta} td.c1`);
204	
205	/** Desde la última página del intento va a summary.php, sin enviar. */
206	export async function irAlResumen(page: Page) {
207	  await page.getByRole('button', { name: /finish attempt/i }).click();
208	  await expect(page).toHaveURL(/summary\.php/);
209	}
210	
211	export const idIntento = (page: Page) => Number(new URL(page.url()).searchParams.get('attempt'));
212	
213	/**
214	 * Celdas de la columna Time del historial de respuestas de comment.php. prepararCaptura no las cubre y la fábrica
215	 * no puede editar helpers.ts desde este spec. Se ubican por el texto del encabezado, no por posición.
216	 */
217	export async function celdasTiempoHistorial(page: Page): Promise<Locator> {
218	  const tabla = page.locator('div.responsehistoryheader table');
219	  const encabezados = await tabla.locator('thead th').allTextContents();
220	  const columna = encabezados.findIndex((t) => t.trim() === 'Time');
221	  expect(columna, `Encabezados del historial: ${encabezados.join(', ')}`).not.toEqual(-1);
222	  return tabla.locator(`tbody tr > :nth-child(${columna + 1})`);
223	}
